[
  {
    "sys_consequence_reasoning": "Five people get to go home instead of none",
    "pda_self_consequence_regret": "That kind of regret would follow me a long time",
    "pda_responsibility": "standing still when I had the chance to act"
  },
  {
    "sys_consequence_reasoning": "The siding stops the train safely, nobody else is hurt",
    "pd_personal_consequence_anxiety": "whether people later question my judgment or blame me"
  },
  {
    "sys_consequence_reasoning": "Five lives against an empty track is not a hard call",
    "pd_personal_consequence_anxiety": "some inquiry afterward picking apart my decision"
  },
  {
    "pd_harm_distress": "Watching workers get hurt... would be unbearable to live with",
    "pd_personal_consequence_anxiety": "deal with the fallout and the complaints"
  },
  {
    "sys_consequence_reasoning": "saving five people outweighs that risk every time",
    "pd_personal_consequence_anxiety": "losing my job over property damage"
  },
  {
    "sys_consequence_reasoning": "Diverting the train costs nothing in terms of danger to anyone",
    "pd_personal_consequence_anxiety": "some part of me dreads that conversation"
  },
  {
    "sys_consequence_reasoning": "Five workers matter more than any inconvenience the siding causes",
    "pd_personal_consequence_anxiety": "worrying that people might second-guess my authority to act"
  },
  {
    "sys_consequence_reasoning": "No one gets hurt either way with that siding option",
    "pd_personal_consequence_anxiety": "imagining some official report questioning my judgment call"
  },
  {
    "sys_consequence_reasoning": "Five people saved, zero cost to anyone else",
    "pda_self_consequence_regret": "What I'd regret is if my quick decision got twisted",
    "pd_personal_consequence_anxiety": "if my quick decision got twisted into some story"
  },
  {
    "sys_consequence_reasoning": "There's no contest between an empty siding and five human lives",
    "pd_personal_consequence_anxiety": "My only real fear afterward is that this incident follows me around"
  }
]
